def compshift(dr,dc,obs):
 t={(r+dr,c+dc) for r,c in base if 0<=r+dr<11 and 0<=c+dc<11}
 q=deque([(4+dr,5+dc)]); comp={(4+dr,5+dc)}
 while q:
  r,c=q.popleft()
  for p in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
   if p in t and p not in obs and p not in comp: comp.add(p);q.append(p)
 return comp
